import java.util.*;
import java.nio.file.*;
public class RiverNetworkEndingsTest {
 static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 static RiverRibbon.Point p(double x,double z){return new RiverRibbon.Point(x,z,2,90);}
 static EnvironmentMap base(int n){var e=new EnvironmentMap(EnvironmentMap.filled(n*n,92));e.water=EnvironmentMap.filled(n*n,62);e.river=new float[n*n];e.material=new byte[n*n];e.snow=new float[n*n];return e;}
 public static void main(String[] args)throws Exception{
  var main=new RiverRibbon.Network(List.of(new RiverRibbon.Segment(p(20,60),p(240,60),3,.8,0)));
  var route=List.of(p(120,10),p(120,40),p(120,100));var joined=RiverJunctions.fit(route,main);check(joined.get(joined.size()-1).z()==60,"crossing becomes endpoint merge");var combined=new ArrayList<>(main.segments);for(int i=1;i<joined.size();i++)combined.add(new RiverRibbon.Segment(joined.get(i-1),joined.get(i),2));check(RiverCrossingAudit.count(new RiverRibbon.Network(combined))==0,"no X crossing");
  var loop=List.of(p(20,20),p(60,60),p(20,60),p(60,20),p(80,20));var clean=RiverJunctions.fit(loop,new RiverRibbon.Network(List.of()));check(clean.get(clean.size()-1).equals(loop.get(loop.size()-1)),"self-loop removal preserves downstream outlet");var cleanSegments=new ArrayList<RiverRibbon.Segment>();for(int i=1;i<clean.size();i++)cleanSegments.add(new RiverRibbon.Segment(clean.get(i-1),clean.get(i),2));check(RiverCrossingAudit.count(new RiverRibbon.Network(cleanSegments))==0,"self crossing erased");
  var lakePoints=List.of(p(100,60),p(100,100),p(100,140),p(100,200));var dryPoints=List.of(p(200,60),p(200,100),p(200,140),p(200,200));
  var lake=new RiverRibbon.SideBranch(lakePoints,1.8,true,1,14);var seasonal=new RiverRibbon.SideBranch(dryPoints,1.8,true,.75,0);var network=main.options(2,List.of(lake,seasonal));var full=base(256);full.snow=null;RiverSideBranches.carve(full,256,0,0,62,network,null);
  for(int z=65;z<201;z++)check(full.waterY(z*256+100,62)>Math.round(full.height[z*256+100]),"lake branch stays connected");check(full.lakeMask[200*256+100]!=0,"terminal lake mask");check(full.waterY(130*256+200,62)>Math.round(full.height[130*256+200]),"seasonal wet reach");check(full.waterY(195*256+200,62)<=Math.round(full.height[195*256+200]),"seasonal dry end");
  var remapped=network.remap(.9,3,62);check(remapped.sideBranches.get(0).terminalRadius()==14&&remapped.sideBranches.get(1).wetFraction()==.75,"ending metadata survives water remap");
  for(int rz=0;rz<2;rz++)for(int rx=0;rx<2;rx++){var tile=base(128);RiverSideBranches.carve(tile,128,rx*128,rz*128,62,network,null);for(int z=0;z<128;z++)for(int x=0;x<128;x++){int i=z*128+x,j=(z+rz*128)*256+x+rx*128;check(tile.height[i]==full.height[j]&&tile.water[i]==full.water[j],"ending geometry matches across region borders");}}
  if(args.length==2){var graph=GraphEditor.readFile(Path.of(args[0]));for(var node:graph.nodes.values())if(node.type==TerrainGraph.Type.RIVERS){node.values.put("naturalEndings",1.0);node.values.put("lakeEndShare",.5);node.values.put("endLakeRadius",20.0);node.values.put("branchReach",Math.max(1.2,node.p("branchReach")));node.values.put("sideBranches",Math.max(24,node.p("sideBranches")));node.values.put("mountainForks",Math.max(24,node.p("mountainForks")));node.values.put("splitDensity",2.0);}GraphEditor.writeFile(graph,Path.of(args[1]));LargeWorldBuilder.configure(16384);LargeWorldBuilder.SEED=4242;LargeWorldBuilder.ACTIVE_GRAPH=graph;var layout=LargeWorldBuilder.layout();try(var out=new java.io.DataOutputStream(Files.newOutputStream(Path.of("dist/river-network-audit.bin")))){out.writeInt(layout.ribbons.segments.size());for(var segment:layout.ribbons.segments){for(var point:List.of(segment.a(),segment.b())){out.writeDouble(point.x());out.writeDouble(point.z());out.writeDouble(point.radius());out.writeDouble(point.water());out.writeDouble(point.discharge());}out.writeDouble(segment.depth());out.writeDouble(segment.maturity());out.writeDouble(segment.curvature());}}var wetSegments=new ArrayList<>(layout.ribbons.segments);for(var branch:layout.ribbons.sideBranches)for(int j=1;j<branch.points().size();j++){double start=(j-1)/(double)(branch.points().size()-1),end=j/(double)(branch.points().size()-1);if(start>=branch.wetFraction())break;var a=branch.points().get(j-1);var b=branch.points().get(j);if(end>branch.wetFraction())b=RiverRibbon.lerp(a,b,(branch.wetFraction()-start)/(end-start));wetSegments.add(new RiverRibbon.Segment(a,b,branch.depth()));}int crossings=RiverCrossingAudit.count(new RiverRibbon.Network(wetSegments));long lakes=layout.ribbons.sideBranches.stream().filter(b->b.terminalRadius()>0).count(),dry=layout.ribbons.sideBranches.stream().filter(b->b.terminalRadius()==0&&b.wetFraction()>.28).count();System.out.println("CITY crossings="+crossings+" lake endings="+lakes+" seasonal endings="+dry+" forks="+layout.mountainForks.size());check(crossings==0,"City accidental crossings");check(lakes>0&&dry>0,"City has both ending types");var ending=layout.ribbons.sideBranches.stream().filter(b->b.terminalRadius()>0).findFirst().orElseThrow();var tip=ending.points().get(ending.points().size()-1);var tile=LargeWorldBuilder.tile(layout,(int)tip.x()/512,(int)tip.z()/512);javax.imageio.ImageIO.write(EnvironmentView.render(tile,0),"png",Path.of("dist/river-branch-endings-city.png").toFile());}
  System.out.println("PASS endpoint junctions, connected lake ending, seasonal dry end, remap and border continuity");
 }
}
